export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed, g = inputs.gravity;
  const ta = u / g, T = 2 * ta, apex = u * u / (2 * g);
  const t = sdk.clamp(time, 0, T);
  const hT = Math.max(0, u * t - g * t * t / 2);
  const vT = u - g * t;
  const open = t >= ta;
  const tau = Math.max(0, t - ta);
  const hD = open ? Math.max(0, apex - g * tau * tau / 2) : apex;
  const vD = open ? -g * tau : 0;
  const aD = open ? -g : 0;
  const aT = -g;
  const yy = (h) => 364 - h * 140;
  const eps = 0.004;
  let sT = 'Falling';
  if (t < eps) sT = 'At launch'; else if (Math.abs(t - ta) < eps) sT = 'At the top'; else if (t < ta) sT = 'Rising'; else if (t >= T - eps) sT = 'At launch height';
  let sD = 'Falling together';
  if (!open) sD = 'Held in place'; else if (t >= T - eps) sD = 'At launch height'; else if (t < ta + 0.1) sD = 'Just released';
  const o = [];
  o.push(...sdk.panel({ id: 'lane.toss', x: 20, y: 36, w: 290, h: 376, title: 'Toss', state: sT, role: 'input' }));
  o.push(...sdk.panel({ id: 'lane.drop', x: 330, y: 36, w: 290, h: 376, title: 'Drop', state: sD, role: 'prediction' }));
  const cxT = 205, cxD = 515;
  o.push(...sdk.groundMark('mark.toss', cxT, 386, 40, 'Launch'));
  o.push(...sdk.groundMark('mark.drop', cxD, 386, 40, 'Launch'));
  o.push(...sdk.gate('gate.drop', cxD, yy(apex) + 26, { open, w: 30, label: 'Gate' }));
  if (open) o.push(sdk.circle('ghost.drop', cxD, yy(apex), 26, { opacity: 0.25 }));
  o.push(sdk.circle('ball.toss', cxT, yy(hT), 26));
  o.push(sdk.circle('ball.drop', cxD, yy(hD), 26));
  const vs = 12, as = 5;
  o.push(...sdk.vector('vec.v.toss', { x: cxT - 40, y: yy(hT) }, { value: vT, direction: 'up' }, { scale: vs, label: 'v' }));
  o.push(...sdk.vector('vec.v.drop', { x: cxD - 40, y: yy(hD) }, { value: vD, direction: 'up' }, { scale: vs, label: 'v' }));
  o.push(...sdk.vector('vec.a.toss', { x: cxT + 40, y: yy(hT) }, { value: aT, direction: 'up' }, { scale: as, label: 'a' }));
  o.push(...sdk.vector('vec.a.drop', { x: cxD + 40, y: yy(hD) }, { value: aD, direction: 'up' }, { scale: as, label: 'a' }));
  const f = (v, d) => sdk.format(v, d);
  o.push(...sdk.callout(28, 90, ['v = ' + f(vT, 2) + ' m/s', 'a = ' + f(aT, 1) + ' m/s²'], { id: 'callout.toss' }));
  o.push(...sdk.callout(338, 90, ['v = ' + f(vD, 2) + ' m/s', 'a = ' + f(aD, 1) + ' m/s²'], { id: 'callout.drop' }));
  const flat = o.flat();
  return {
    frame: { width: 640, height: 420, objects: flat, readouts: [
      { id: 'tossedVelocity', value: vT }, { id: 'tossedAcceleration', value: aT },
      { id: 'dropVelocity', value: vD }, { id: 'dropAcceleration', value: aD }] },
    quantities: { launchSpeed: u, gravity: g, apexTime: ta, apexHeight: apex, tossedVelocity: vT, tossedAcceleration: aT, tossedHeight: hT, dropVelocity: vD, dropAcceleration: aD, dropHeight: hD }
  };
}
